public interface IEntity { int Id { get; set; } }

public class InMemoryRepository<T> where T : class, IEntity
{
    private readonly Dictionary<int, T> _items = new();

    public T Add(T item) { _items[item.Id] = item; return item; }
    public T? GetById(int id) => _items.GetValueOrDefault(id);
}

// Generic METHOD: the type parameter is on the method, and is usually inferred
public static T Max<T>(IEnumerable<T> items) where T : IComparable<T>
    => items.Aggregate((a, b) => a.CompareTo(b) >= 0 ? a : b);

int biggest = Max(new[] { 3, 9, 4 });          // T inferred as int
string last = Max(new[] { "pear", "apple" });  // T inferred as string
